#include <bits/stdc++.h>
using namespace std; class Solution{public:int getMaxGridHappiness(int m,int n,int introvertsCount,int extrovertsCount){int I=introvertsCount,E=extrovertsCount;if(n>m)swap(n,m);int k=1;for(int i=0;i<n;i++)k*=3;vector<int>h(k),a(k),b(k);for(int x=0;x<k;x++){int q=x,p=0;for(int j=0;j<n;j++){int d=q%3;q/=3;if(d==1)h[x]+=120,a[x]++;else if(d==2)h[x]+=40,b[x]++;if(d&&p)h[x]+=(d==1?-30:20)+(p==1?-30:20);p=d;}}map<tuple<int,int,int,int>,int>M;function<int(int,int,int,int)>f=[&](int r,int i,int e,int p){if(r==m)return 0;auto z=make_tuple(r,i,e,p);if(M.count(z))return M[z];int v=0;for(int c=0;c<k;c++)if(a[c]<=i&&b[c]<=e){int x=p,y=c,s=0;for(int j=0;j<n;j++){int u=x%3,d=y%3;x/=3;y/=3;if(u&&d)s+=(u==1?-30:20)+(d==1?-30:20);}v=max(v,h[c]+s+f(r+1,i-a[c],e-b[c],c));}return M[z]=v;};return f(0,I,E,0);}};
